package com.example.concurrentrequestscope;

import com.example.concurrentrequestscope.exception.ConcurrentRequestScopeCapacityException;
import com.example.concurrentrequestscope.exception.ConcurrentRequestScopeCleanupException;
import com.example.concurrentrequestscope.exception.ConcurrentRequestScopeSnapshotException;
import com.example.concurrentrequestscope.internal.ConcurrentRequestScopeEntry;
import com.example.concurrentrequestscope.internal.ConcurrentRequestScopeSettings;
import com.example.concurrentrequestscope.internal.ConcurrentRequestScopeState;
import com.example.concurrentrequestscope.internal.ScopeKeyResolver;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.config.Scope;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

import java.time.Duration;
import java.util.Objects;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;

public class ConcurrentRequestScope implements Scope {

    private static final System.Logger LOGGER = System.getLogger(ConcurrentRequestScope.class.getName());
    private static final String CLEANUP_CALLBACK_NAME =
            ConcurrentRequestScope.class.getName() + ".cleanup";

    private final ConcurrentRequestScopeState state;
    private final ScopeKeyResolver keyResolver;
    private final ScheduledExecutorService staleEntryCleanupExecutor;

    public ConcurrentRequestScope() {
        this(ConcurrentRequestScopeSettings.defaults());
    }

    public ConcurrentRequestScope(ConcurrentRequestScopeSettings settings) {
        this(new ConcurrentRequestScopeState(settings), new ScopeKeyResolver(), true);
    }

    public ConcurrentRequestScope(ConcurrentRequestScopeState state, ScopeKeyResolver keyResolver) {
        this(state, keyResolver, false);
    }

    private ConcurrentRequestScope(
            ConcurrentRequestScopeState state,
            ScopeKeyResolver keyResolver,
            boolean startStaleEntryCleanup) {
        this.state = Objects.requireNonNull(state, "state must not be null");
        this.keyResolver = Objects.requireNonNull(keyResolver, "keyResolver must not be null");
        this.staleEntryCleanupExecutor = startStaleEntryCleanup ? startStaleEntryCleanup() : null;
    }

    @Override
    public Object get(String name, ObjectFactory<?> objectFactory) {
        Objects.requireNonNull(name, "bean name must not be null");
        Objects.requireNonNull(objectFactory, "objectFactory must not be null");
        ConcurrentRequestScopeEntry entry = getOrCreateEntry(RequestContextHolder.currentRequestAttributes());
        return entry.getOrCreateBean(name, objectFactory);
    }

    @Override
    public Object remove(String name) {
        RequestAttributes attrs = RequestContextHolder.getRequestAttributes();
        if (attrs == null) {
            return null;
        }
        ConcurrentRequestScopeEntry entry = state.getEntry(keyResolver.scopeKey(attrs));
        return entry != null ? entry.removeBean(name) : null;
    }

    @Override
    public void registerDestructionCallback(String name, Runnable callback) {
        Objects.requireNonNull(name, "bean name must not be null");
        Objects.requireNonNull(callback, "destruction callback must not be null");
        RequestAttributes attrs = RequestContextHolder.currentRequestAttributes();
        ConcurrentRequestScopeEntry entry = state.getEntry(keyResolver.scopeKey(attrs));
        if (entry == null) {
            throw new IllegalStateException(
                    "[ConcurrentRequestScope] cannot register destruction callback before request entry exists");
        }
        entry.registerDestructionCallback(name, callback);
    }

    @Override
    public Object resolveContextualObject(String key) {
        RequestAttributes attrs = RequestContextHolder.currentRequestAttributes();
        return attrs.resolveReference(key);
    }

    @Override
    public String getConversationId() {
        RequestAttributes attrs = RequestContextHolder.getRequestAttributes();
        if (attrs == null) {
            return null;
        }
        ConcurrentRequestScopeEntry entry = state.getEntry(keyResolver.scopeKey(attrs));
        return entry != null ? entry.conversationId() : null;
    }

    void clearForTesting() {
        state.clearForTesting();
    }

    ConcurrentRequestScopeState stateForTesting() {
        return state;
    }

    Object scopeKeyForTesting(RequestAttributes attrs) {
        return keyResolver.scopeKey(attrs);
    }

    void cleanupScopeEntryForTesting(Object key, ConcurrentRequestScopeEntry expected) {
        cleanupScopeEntry(key, expected);
    }

    int cleanupStaleEntriesForTesting() {
        return cleanupStaleEntries();
    }

    private ConcurrentRequestScopeEntry getOrCreateEntry(RequestAttributes attrs) {
        Object key = keyResolver.scopeKey(attrs);
        ConcurrentRequestScopeEntry existing = state.getEntry(key);
        if (existing != null) {
            existing.touch(state.nowNanos());
            return existing;
        }
        if (keyResolver.isSnapshot(attrs)) {
            throw new ConcurrentRequestScopeSnapshotException(
                    "[ConcurrentRequestScope] missing request entry from propagated snapshot attributes is rejected: "
                            + attrs.getClass().getSimpleName());
        }
        if (!state.tryAcquireCapacity()) {
            throw new ConcurrentRequestScopeCapacityException(
                    "[ConcurrentRequestScope] capacity limit reached: max active requests = "
                            + state.settings().maxActiveRequests());
        }
        ConcurrentRequestScopeEntry candidate = state.createEntry();
        ConcurrentRequestScopeEntry winner = state.putEntryIfAbsent(key, candidate);
        if (winner != null) {
            state.releaseCapacity();
            winner.touch(state.nowNanos());
            return winner;
        }
        try {
            attrs.registerDestructionCallback(
                    CLEANUP_CALLBACK_NAME,
                    () -> cleanupScopeEntry(key, candidate),
                    RequestAttributes.SCOPE_REQUEST);
        } catch (RuntimeException e) {
            if (state.removeEntryIfSame(key, candidate)) {
                state.releaseCapacity();
            }
            throw new ConcurrentRequestScopeCleanupException(
                    "[ConcurrentRequestScope] cleanup callback registration failed for conversation "
                            + candidate.conversationId(),
                    e);
        }
        return candidate;
    }

    private ScheduledExecutorService startStaleEntryCleanup() {
        ConcurrentRequestScopeSettings settings = state.settings();
        if (!settings.staleEntryCleanupEnabled()) {
            return null;
        }

        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor(staleCleanerThreadFactory());
        Duration scanInterval = settings.staleEntryScanInterval();
        executor.scheduleWithFixedDelay(
                this::cleanupStaleEntriesSafely,
                scanInterval.toNanos(),
                scanInterval.toNanos(),
                TimeUnit.NANOSECONDS);
        return executor;
    }

    private static ThreadFactory staleCleanerThreadFactory() {
        return runnable -> {
            Thread thread = Thread.ofPlatform()
                    .name("concurrent-request-scope-stale-cleaner")
                    .unstarted(runnable);
            thread.setDaemon(true);
            return thread;
        };
    }

    private void cleanupStaleEntriesSafely() {
        try {
            cleanupStaleEntries();
        } catch (RuntimeException e) {
            LOGGER.log(System.Logger.Level.ERROR,
                    "[ConcurrentRequestScope] stale entry cleanup scan failed",
                    e);
        }
    }

    private int cleanupStaleEntries() {
        ConcurrentRequestScopeSettings settings = state.settings();
        if (!settings.staleEntryCleanupEnabled()) {
            return 0;
        }
        long ttlNanos = settings.staleEntryTtl().toNanos();
        return state.forEachStaleEntry(ttlNanos, this::cleanupStaleEntry);
    }

    private void cleanupStaleEntry(Object key, ConcurrentRequestScopeEntry expected) {
        if (!state.removeEntryIfSame(key, expected)) {
            return;
        }
        try {
            int failures = expected.runDestructionCallbacks((name, thrown) ->
                    LOGGER.log(System.Logger.Level.ERROR,
                            "[ConcurrentRequestScope] destruction callback failed during stale cleanup for bean '"
                                    + name + "'",
                            thrown));
            state.recordCleanupFailures(failures);
            state.recordStaleEntryCleanup();
            LOGGER.log(System.Logger.Level.WARNING,
                    "[ConcurrentRequestScope] stale request entry cleaned up for conversation "
                            + expected.conversationId());
        } finally {
            state.releaseCapacity();
        }
    }

    private void cleanupScopeEntry(Object key, ConcurrentRequestScopeEntry expected) {
        if (!state.removeEntryIfSame(key, expected)) {
            return;
        }
        try {
            int failures = expected.runDestructionCallbacks((name, thrown) ->
                    LOGGER.log(System.Logger.Level.ERROR,
                            "[ConcurrentRequestScope] destruction callback failed for bean '" + name + "'",
                            thrown));
            state.recordCleanupFailures(failures);
        } finally {
            state.releaseCapacity();
        }
    }
}

package com.example.concurrentrequestscope.internal;

import com.example.concurrentrequestscope.ConcurrentRequestScope;
import com.example.concurrentrequestscope.ConcurrentRequestScopeNames;
import com.example.concurrentrequestscope.ConcurrentRequestScopeProperties;
import io.micrometer.context.ContextRegistry;
import org.springframework.beans.BeansException;
import org.springframework.beans.factory.BeanCreationException;
import org.springframework.beans.factory.config.BeanFactoryPostProcessor;
import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
import org.springframework.boot.context.properties.bind.Binder;
import org.springframework.core.env.Environment;
import org.springframework.web.context.request.RequestAttributesThreadLocalAccessor;

import java.util.Objects;

public final class ConcurrentRequestScopeBeanFactoryPostProcessor implements BeanFactoryPostProcessor {

    private final Environment environment;

    public ConcurrentRequestScopeBeanFactoryPostProcessor(Environment environment) {
        this.environment = Objects.requireNonNull(environment, "environment must not be null");
    }

    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) throws BeansException {
        registerRequestAttributesThreadLocalAccessor();

        if (beanFactory.getRegisteredScope(ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE) != null) {
            throw new BeanCreationException(
                    "ConcurrentRequestScope already registered for scope name '"
                            + ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE + "'");
        }

        ConcurrentRequestScopeProperties properties = Binder.get(environment)
                .bind("concurrent-request-scope", ConcurrentRequestScopeProperties.class)
                .orElseGet(ConcurrentRequestScopeProperties::new);

        beanFactory.registerScope(
                ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE,
                new ConcurrentRequestScope(properties.toSettings()));
    }

    private static void registerRequestAttributesThreadLocalAccessor() {
        ContextRegistry registry = ContextRegistry.getInstance();
        boolean alreadyRegistered = registry.getThreadLocalAccessors().stream()
                .anyMatch(accessor -> accessor instanceof RequestAttributesThreadLocalAccessor);
        if (!alreadyRegistered) {
            registry.registerThreadLocalAccessor(new RequestAttributesThreadLocalAccessor());
        }
    }
}
package com.example.concurrentrequestscope.internal;

import com.example.concurrentrequestscope.exception.ConcurrentRequestScopeBackdoorException;

import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BiConsumer;
import java.util.function.LongSupplier;

public final class ConcurrentRequestScopeState {

    private final ConcurrentRequestScopeSettings settings;
    private final ConcurrentHashMap<Object, ConcurrentRequestScopeEntry> entries = new ConcurrentHashMap<>(512);
    private final Semaphore capacity;
    private final LongSupplier nanoTimeSource;
    private final AtomicLong conversationIdCounter = new AtomicLong();
    private final AtomicLong cleanupFailureCounter = new AtomicLong();
    private final AtomicLong staleEntryCleanupCounter = new AtomicLong();
    private final Object capacityResetLock = new Object();

    public ConcurrentRequestScopeState(ConcurrentRequestScopeSettings settings) {
        this(settings, System::nanoTime);
    }

    public ConcurrentRequestScopeState(ConcurrentRequestScopeSettings settings, LongSupplier nanoTimeSource) {
        this.settings = Objects.requireNonNull(settings, "settings must not be null");
        this.nanoTimeSource = Objects.requireNonNull(nanoTimeSource, "nanoTimeSource must not be null");
        this.capacity = new Semaphore(settings.maxActiveRequests());
    }

    public ConcurrentRequestScopeSettings settings() {
        return settings;
    }

    public boolean tryAcquireCapacity() {
        return capacity.tryAcquire();
    }

    public void releaseCapacity() {
        capacity.release();
    }

    public int availableCapacity() {
        return capacity.availablePermits();
    }

    public long activeEntryCount() {
        return entries.mappingCount();
    }

    public long nextConversationSequence() {
        return conversationIdCounter.incrementAndGet();
    }

    public long nowNanos() {
        return nanoTimeSource.getAsLong();
    }

    public ConcurrentRequestScopeEntry createEntry() {
        return new ConcurrentRequestScopeEntry(nextConversationSequence(), nowNanos());
    }

    public void recordCleanupFailures(long failures) {
        if (failures > 0) {
            cleanupFailureCounter.addAndGet(failures);
        }
    }

    public long cleanupFailureCount() {
        return cleanupFailureCounter.get();
    }

    public void recordStaleEntryCleanup() {
        staleEntryCleanupCounter.incrementAndGet();
    }

    public long staleEntryCleanupCount() {
        return staleEntryCleanupCounter.get();
    }

    public ConcurrentRequestScopeEntry getEntry(Object key) {
        return entries.get(key);
    }

    public ConcurrentRequestScopeEntry putEntryIfAbsent(Object key, ConcurrentRequestScopeEntry entry) {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(entry, "entry must not be null");
        return entries.putIfAbsent(key, entry);
    }

    public boolean removeEntryIfSame(Object key, ConcurrentRequestScopeEntry entry) {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(entry, "entry must not be null");
        return entries.remove(key, entry);
    }

    public boolean capacityInvariantHolds() {
        return availableCapacity() + activeEntryCount() == settings.maxActiveRequests();
    }

    public int forEachStaleEntry(long ttlNanos, BiConsumer<Object, ConcurrentRequestScopeEntry> cleanup) {
        Objects.requireNonNull(cleanup, "cleanup must not be null");
        long nowNanos = nowNanos();
        AtomicLong candidates = new AtomicLong();
        entries.forEach((key, entry) -> {
            if (entry.staleAt(nowNanos, ttlNanos)) {
                candidates.incrementAndGet();
                cleanup.accept(key, entry);
            }
        });
        return Math.toIntExact(candidates.get());
    }

    public void clearForTesting() {
        if (!settings.testingClearEnabled()) {
            throw new ConcurrentRequestScopeBackdoorException(
                    "Test cleanup is disabled. Set concurrent-request-scope.testing.clear-enabled=true in test wiring.");
        }
        entries.clear();
        conversationIdCounter.set(0);
        cleanupFailureCounter.set(0);
        staleEntryCleanupCounter.set(0);
        synchronized (capacityResetLock) {
            capacity.drainPermits();
            capacity.release(settings.maxActiveRequests());
        }
    }
}
package com.example.concurrentrequestscope.internal;

import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.BeanCurrentlyInCreationException;

import java.util.HashSet;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BiConsumer;

public final class ConcurrentRequestScopeEntry {

    private final ConcurrentHashMap<String, BeanSlot> slots = new ConcurrentHashMap<>();
    private final DestructionCallbackRegistry destructionCallbacks = new DestructionCallbackRegistry();
    private final String conversationId;
    private final long createdAtNanos;
    private final AtomicLong lastAccessAtNanos;
    private final ThreadLocal<Set<String>> creatingBeans = ThreadLocal.withInitial(HashSet::new);

    public ConcurrentRequestScopeEntry(long conversationSequence) {
        this(conversationSequence, System.nanoTime());
    }

    public ConcurrentRequestScopeEntry(long conversationSequence, long createdAtNanos) {
        this.conversationId = Long.toString(conversationSequence);
        this.createdAtNanos = createdAtNanos;
        this.lastAccessAtNanos = new AtomicLong(createdAtNanos);
    }

    public String conversationId() {
        return conversationId;
    }

    public long createdAtNanos() {
        return createdAtNanos;
    }

    public long lastAccessAtNanos() {
        return lastAccessAtNanos.get();
    }

    public void touch(long nowNanos) {
        lastAccessAtNanos.accumulateAndGet(nowNanos, Math::max);
    }

    public boolean staleAt(long nowNanos, long ttlNanos) {
        return nowNanos - lastAccessAtNanos.get() >= ttlNanos;
    }

    public Object getOrCreateBean(String name, ObjectFactory<?> objectFactory) {
        Objects.requireNonNull(name, "bean name must not be null");
        Objects.requireNonNull(objectFactory, "objectFactory must not be null");
        Set<String> creating = creatingBeans.get();
        if (!creating.add(name)) {
            throw new BeanCurrentlyInCreationException(name,
                    "[ConcurrentRequestScope] detected circular creation for bean '" + name + "'");
        }
        BeanSlot slot = slots.computeIfAbsent(name, BeanSlot::new);
        try {
            return slot.getOrCreate(objectFactory);
        } catch (RuntimeException | Error e) {
            if (!slot.initialized()) {
                slots.remove(name, slot);
            }
            throw e;
        } finally {
            creating.remove(name);
            if (creating.isEmpty()) {
                creatingBeans.remove();
            }
        }
    }

    public Object removeBean(String name) {
        Objects.requireNonNull(name, "bean name must not be null");
        destructionCallbacks.remove(name);
        BeanSlot removed = slots.remove(name);
        return removed != null ? removed.valueOrNull() : null;
    }

    public void registerDestructionCallback(String name, Runnable callback) {
        destructionCallbacks.register(name, callback);
    }

    public int runDestructionCallbacks(BiConsumer<String, Throwable> failureHandler) {
        return destructionCallbacks.runBestEffort(failureHandler);
    }
}
package com.example.concurrentrequestscope.internal;

import org.springframework.beans.factory.config.BeanDefinition;
import org.springframework.beans.factory.support.BeanDefinitionRegistry;
import org.springframework.beans.factory.support.RootBeanDefinition;
import org.springframework.context.EnvironmentAware;
import org.springframework.context.annotation.ImportBeanDefinitionRegistrar;
import org.springframework.core.env.Environment;
import org.springframework.core.type.AnnotationMetadata;

public final class ConcurrentRequestScopeRegistrar implements ImportBeanDefinitionRegistrar, EnvironmentAware {

    static final String BEAN_NAME = "concurrentRequestScopeBeanFactoryPostProcessor";

    private Environment environment;

    @Override
    public void setEnvironment(Environment environment) {
        this.environment = environment;
    }

    @Override
    public void registerBeanDefinitions(AnnotationMetadata importingClassMetadata, BeanDefinitionRegistry registry) {
        if (registry.containsBeanDefinition(BEAN_NAME)) {
            return;
        }

        RootBeanDefinition beanDefinition = new RootBeanDefinition(ConcurrentRequestScopeBeanFactoryPostProcessor.class);
        beanDefinition.setRole(BeanDefinition.ROLE_INFRASTRUCTURE);
        beanDefinition.getConstructorArgumentValues().addIndexedArgumentValue(0, environment);
        registry.registerBeanDefinition(BEAN_NAME, beanDefinition);
    }
}

package com.example.concurrentrequestscope;

import com.example.concurrentrequestscope.exception.ConcurrentRequestScopeSnapshotException;
import com.example.concurrentrequestscope.internal.ConcurrentRequestScopeEntry;
import com.example.concurrentrequestscope.internal.ConcurrentRequestScopeSettings;
import com.example.concurrentrequestscope.internal.ConcurrentRequestScopeState;
import com.example.concurrentrequestscope.internal.ScopeKeyResolver;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.LongSupplier;

import static com.example.concurrentrequestscope.support.ConcurrentRequestScopeStateAssertions.assertBaseline;
import static com.example.concurrentrequestscope.support.ConcurrentRequestScopeStateAssertions.assertScopeState;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ConcurrentRequestScopeTtlCleanupTest {

    private static final Duration TTL = Duration.ofSeconds(10);

    private ManualNanoTime nanoTime;
    private ConcurrentRequestScopeState state;
    private ConcurrentRequestScope scope;

    @BeforeEach
    void setUp() {
        nanoTime = new ManualNanoTime();
        state = new ConcurrentRequestScopeState(
                new ConcurrentRequestScopeSettings(5, true, true, TTL, Duration.ofSeconds(1)),
                nanoTime);
        scope = new ConcurrentRequestScope(state, new ScopeKeyResolver());
    }

    @AfterEach
    void tearDown() {
        RequestContextHolder.resetRequestAttributes();
        scope.clearForTesting();
    }

    @Test
    void expiredEntryCleanupReturnsActiveEntriesAndCapacityToBaseline() {
        RecordingServletRequestAttributes attrs =
                new RecordingServletRequestAttributes(new MockHttpServletRequest());
        AtomicInteger callbackRuns = new AtomicInteger();
        RequestContextHolder.setRequestAttributes(attrs);

        scope.get("bean", Object::new);
        scope.registerDestructionCallback("bean", callbackRuns::incrementAndGet);
        assertScopeState(state, 1, 4);

        nanoTime.advance(TTL.plusNanos(1));
        assertEquals(1, scope.cleanupStaleEntriesForTesting());

        assertEquals(1, callbackRuns.get());
        assertEquals(1, state.staleEntryCleanupCount());
        assertBaseline(state);
    }

    @Test
    void normalCleanupAndTtlCleanupRaceDoesNotOverReleaseCapacity() {
        RecordingServletRequestAttributes attrs =
                new RecordingServletRequestAttributes(new MockHttpServletRequest());
        RequestContextHolder.setRequestAttributes(attrs);

        scope.get("bean", Object::new);
        attrs.runCompletionCallback();
        nanoTime.advance(TTL.plusNanos(1));

        assertEquals(0, scope.cleanupStaleEntriesForTesting());
        assertBaseline(state);
    }

    @Test
    void staleExpectedEntryCannotRemoveNewerEntryForSameKey() {
        RecordingServletRequestAttributes attrs =
                new RecordingServletRequestAttributes(new MockHttpServletRequest());
        RequestContextHolder.setRequestAttributes(attrs);
        Object key = scope.scopeKeyForTesting(attrs);

        scope.get("old", Object::new);
        ConcurrentRequestScopeEntry oldEntry = state.getEntry(key);
        attrs.runCompletionCallback();

        scope.get("new", Object::new);
        ConcurrentRequestScopeEntry newEntry = state.getEntry(key);

        scope.cleanupScopeEntryForTesting(key, oldEntry);

        assertSame(newEntry, state.getEntry(key));
        assertScopeState(state, 1, 4);
    }

    @Test
    void staleEntryCleanupKeepsMissingEntrySnapshotFailSecure() {
        MockHttpServletRequest request = new MockHttpServletRequest();
        RecordingServletRequestAttributes ownerAttrs = new RecordingServletRequestAttributes(request);
        RequestContextHolder.setRequestAttributes(ownerAttrs);

        scope.get("bean", Object::new);
        nanoTime.advance(TTL.plusNanos(1));
        scope.cleanupStaleEntriesForTesting();

        RequestContextHolder.setRequestAttributes(new RecordingSnapshotServletRequestAttributes(request));

        assertThrows(ConcurrentRequestScopeSnapshotException.class, () -> scope.get("lateWorker", Object::new));
        assertBaseline(state);
    }

    private static final class ManualNanoTime implements LongSupplier {

        private long now;

        @Override
        public long getAsLong() {
            return now;
        }

        void advance(Duration duration) {
            now += duration.toNanos();
        }
    }

    private static class RecordingServletRequestAttributes extends ServletRequestAttributes {

        private Runnable callback;

        RecordingServletRequestAttributes(MockHttpServletRequest request) {
            super(request);
        }

        @Override
        public void registerDestructionCallback(String name, Runnable callback, int scope) {
            this.callback = callback;
            super.registerDestructionCallback(name, callback, scope);
        }

        void runCompletionCallback() {
            callback.run();
        }
    }

    private static final class RecordingSnapshotServletRequestAttributes extends RecordingServletRequestAttributes {

        private RecordingSnapshotServletRequestAttributes(MockHttpServletRequest request) {
            super(request);
        }
    }
}
package com.example.concurrentrequestscope;

import com.example.concurrentrequestscope.exception.ConcurrentRequestScopeCapacityException;
import io.micrometer.context.ContextRegistry;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.config.BeanFactoryPostProcessor;
import org.springframework.beans.factory.config.ConfigurableBeanFactory;
import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.ScopedProxyMode;
import org.springframework.context.support.SimpleThreadScope;
import org.springframework.core.Ordered;
import org.springframework.core.PriorityOrdered;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.context.request.RequestAttributesThreadLocalAccessor;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class ConcurrentRequestScopeEnablementTest {

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner()
            .withUserConfiguration(EnabledConfig.class);

    @BeforeEach
    void setUp() {
        RequestContextHolder.resetRequestAttributes();
        removeRequestAttributesAccessor();
    }

    @AfterEach
    void tearDown() {
        RequestContextHolder.resetRequestAttributes();
        removeRequestAttributesAccessor();
    }

    @Test
    void enableAnnotationRegistersScopeAndScopedBeanResolvesInRequest() {
        contextRunner
                .withPropertyValues("concurrent-request-scope.testing.clear-enabled=true")
                .run(context -> {
                    ConfigurableBeanFactory beanFactory = context.getSourceApplicationContext().getBeanFactory();
                    org.springframework.beans.factory.config.Scope registeredScope =
                            beanFactory.getRegisteredScope(ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE);

                    assertThat(registeredScope).isInstanceOf(ConcurrentRequestScope.class);

                    ServletRequestAttributes requestAttributes =
                            new ServletRequestAttributes(new MockHttpServletRequest());
                    RequestContextHolder.setRequestAttributes(requestAttributes);

                    ScopedProbe probe = context.getBean(ScopedProbe.class);
                    assertThat(probe.id()).isEqualTo(probe.id());

                    ((ConcurrentRequestScope) registeredScope).clearForTesting();
                    requestAttributes.requestCompleted();
                });
    }

    @Test
    void maxActiveRequestsPropertyLimitsActiveScopeEntries() {
        contextRunner
                .withPropertyValues(
                        "concurrent-request-scope.max-active-requests=3",
                        "concurrent-request-scope.testing.clear-enabled=true")
                .run(context -> {
                    ConcurrentRequestScope scope = registeredConcurrentRequestScope(context.getSourceApplicationContext()
                            .getBeanFactory());

                    createScopedObject(scope, new MockHttpServletRequest());
                    createScopedObject(scope, new MockHttpServletRequest());
                    createScopedObject(scope, new MockHttpServletRequest());

                    assertThatThrownBy(() -> createScopedObject(scope, new MockHttpServletRequest()))
                            .isInstanceOf(ConcurrentRequestScopeCapacityException.class);

                    scope.clearForTesting();
                });
    }

    @Test
    void duplicateScopeRegistrationFailsFast() {
        new ApplicationContextRunner()
                .withUserConfiguration(DuplicateScopeConfig.class, EnabledConfig.class)
                .run(context -> {
                    assertThat(context).hasFailed();
                    assertThat(context.getStartupFailure())
                            .hasMessageContaining("ConcurrentRequestScope already registered")
                            .hasMessageContaining(ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE);
                });
    }

    @Test
    void repeatedEnablementRegistersOneRequestAttributesAccessor() {
        contextRunner.run(context -> assertThat(countRequestAttributesAccessors()).isEqualTo(1));
        contextRunner.run(context -> assertThat(countRequestAttributesAccessors()).isEqualTo(1));
    }

    private static void createScopedObject(ConcurrentRequestScope scope, MockHttpServletRequest request) {
        ServletRequestAttributes requestAttributes = new ServletRequestAttributes(request);
        RequestContextHolder.setRequestAttributes(requestAttributes);
        scope.get("probe-" + UUID.randomUUID(), Object::new);
    }

    private static ConcurrentRequestScope registeredConcurrentRequestScope(ConfigurableListableBeanFactory beanFactory) {
        return (ConcurrentRequestScope) beanFactory.getRegisteredScope(
                ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE);
    }

    private static long countRequestAttributesAccessors() {
        return ContextRegistry.getInstance().getThreadLocalAccessors().stream()
                .filter(accessor -> accessor instanceof RequestAttributesThreadLocalAccessor)
                .count();
    }

    private static void removeRequestAttributesAccessor() {
        ContextRegistry.getInstance().removeThreadLocalAccessor(RequestAttributesThreadLocalAccessor.KEY);
    }

    @Configuration(proxyBeanMethods = false)
    @EnableConcurrentRequestScope
    static class EnabledConfig {

        @Bean
        @org.springframework.context.annotation.Scope(
                value = ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE,
                proxyMode = ScopedProxyMode.TARGET_CLASS)
        ScopedProbe scopedProbe() {
            return new ScopedProbe();
        }
    }

    @Configuration(proxyBeanMethods = false)
    static class DuplicateScopeConfig {

        @Bean
        static BeanFactoryPostProcessor duplicateConcurrentRequestScopeRegistrar() {
            return new DuplicateScopePostProcessor();
        }
    }

    static final class DuplicateScopePostProcessor implements BeanFactoryPostProcessor, PriorityOrdered {

        @Override
        public int getOrder() {
            return Ordered.HIGHEST_PRECEDENCE;
        }

        @Override
        public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) {
            beanFactory.registerScope(
                    ConcurrentRequestScopeNames.CONCURRENT_REQUEST_SCOPE,
                    new SimpleThreadScope());
        }
    }

    static class ScopedProbe {

        private final String id = UUID.randomUUID().toString();

        String id() {
            return id;
        }
    }
